-- Owner-approved November 6: separate VQ editorial publishing from the owner's account.
-- No login credentials, admin/contributor role, follower transfer, or new publication.
create table private.dealer_attribution_history (
 post_id uuid primary key references public.community_posts(id),
 original_user_id uuid not null references auth.users(id),
 original_author_name text not null,
 dealer_user_id uuid not null references auth.users(id),
 changed_at timestamptz not null default now()
);
alter table private.dealer_attribution_history enable row level security;
revoke all on private.dealer_attribution_history from public,anon,authenticated,service_role;

do $dealer$
declare dealer uuid; old_author uuid; body text; signature text;
begin
 select user_id into strict old_author from private.zone_automation where name='nba_threes';
 if old_author is distinct from (select user_id from private.zone_automation where name='sports_editorial') then
  raise exception 'Publisher mappings differ; review before changing';
 end if;
 if exists(select 1 from public.community_profiles where lower(username)='thedealer') then
  raise exception 'TheDealer username already exists; do not take over another account';
 end if;
 dealer:=gen_random_uuid();
 -- An attribution-only principal: no email, password, phone, identities or sessions; login banned.
 insert into auth.users(id,aud,role,raw_app_meta_data,raw_user_meta_data,banned_until,created_at,updated_at)
 values(dealer,'authenticated','authenticated','{"publisher":"vq_dealer"}'::jsonb,
  '{"display_name":"The Dealer"}'::jsonb,'infinity'::timestamptz,now(),now());
 -- Do not announce the internal publisher as a new member signup.
 delete from private.push_deliveries where event_key='signup:'||dealer::text;
 insert into public.community_profiles(user_id,username,avatar,visible)
 values(dealer,'TheDealer', 'data:image/jpeg;base64,',true);
 if not coalesce(private.age_eligible(dealer),false) then
  raise exception 'Publisher is not eligible under current policy; no age attestation is fabricated';
 end if;
 -- Save the original author independently. Source journals and selection authors are immutable.
 insert into private.dealer_attribution_history(post_id,original_user_id,original_author_name,dealer_user_id)
 select id,user_id,author_name,dealer from public.community_posts
 where user_id=old_author and photo_path is null
  and (card='vq-publication:v1' or card ~ '^nba-threes:[0-9]{4}-[0-9]{2}-[0-9]{2}$');
 update public.community_posts p set user_id=dealer,author_name='TheDealer'
 from private.dealer_attribution_history h where h.post_id=p.id;
 update private.zone_automation set user_id=dealer where name in ('nba_threes','sports_editorial');
 insert into private.zone_automation(name,user_id) values('vq_dealer',dealer);
 -- Change only the identity literal in the two existing server-only provenance checks.
 foreach signature in array array['private.attach_zone_automated_card()','private.community_post_card_guard()'] loop
  select pg_get_functiondef(signature::regprocedure) into body;
  if position('p.username=''MikeQ''' in body)=0 then raise exception 'Publisher guard changed: %',signature;end if;
  execute replace(body,'p.username=''MikeQ''','p.username=''TheDealer''');
 end loop;
end $dealer$;
